--
-- Super Admin access and shared web/mobile application configuration
-- This section is part of the same schema used by the website and mobile app.
--

ALTER TABLE `user_type`
  MODIFY `role` varchar(50) NOT NULL;

ALTER TABLE `hospitals`
  ADD COLUMN `is_active` tinyint(1) NOT NULL DEFAULT 1,
  ADD COLUMN `archived_at` datetime DEFAULT NULL;

ALTER TABLE `barangays`
  ADD COLUMN `is_active` tinyint(1) NOT NULL DEFAULT 1,
  ADD COLUMN `archived_at` datetime DEFAULT NULL;

CREATE TABLE `app_roles` (
  `role_key` varchar(50) NOT NULL,
  `display_name` varchar(100) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `is_system` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`role_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


ALTER TABLE `user_type`
  ADD CONSTRAINT `fk_user_type_app_role` FOREIGN KEY (`role`) REFERENCES `app_roles` (`role_key`) ON UPDATE CASCADE;

CREATE TABLE `app_permissions` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `permission_key` varchar(100) NOT NULL,
  `display_name` varchar(120) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `platform_scope` enum('shared','web','mobile') NOT NULL DEFAULT 'shared',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_app_permissions_key_scope` (`permission_key`,`platform_scope`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `app_role_permissions` (
  `role_key` varchar(50) NOT NULL,
  `permission_id` int(10) UNSIGNED NOT NULL,
  `granted_by_user_id` int(10) UNSIGNED DEFAULT NULL,
  `granted_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`role_key`,`permission_id`),
  KEY `idx_app_role_permissions_permission` (`permission_id`),
  KEY `idx_app_role_permissions_granted_by` (`granted_by_user_id`),
  CONSTRAINT `fk_app_role_permissions_role` FOREIGN KEY (`role_key`) REFERENCES `app_roles` (`role_key`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_app_role_permissions_permission` FOREIGN KEY (`permission_id`) REFERENCES `app_permissions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_app_role_permissions_granted_by` FOREIGN KEY (`granted_by_user_id`) REFERENCES `user_type` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT 'super_admin', `id` FROM `app_permissions`;

CREATE TABLE `application_settings` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform_scope` enum('shared','web','mobile') NOT NULL DEFAULT 'shared',
  `setting_key` varchar(120) NOT NULL,
  `setting_value` longtext,
  `value_type` enum('string','integer','boolean','json') NOT NULL DEFAULT 'string',
  `description` varchar(255) DEFAULT NULL,
  `updated_by_user_id` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_application_settings_scope_key` (`platform_scope`,`setting_key`),
  KEY `idx_application_settings_updated_by` (`updated_by_user_id`),
  CONSTRAINT `fk_application_settings_updated_by` FOREIGN KEY (`updated_by_user_id`) REFERENCES `user_type` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `application_branding` (
  `platform_scope` enum('shared','web','mobile') NOT NULL,
  `app_name` varchar(120) DEFAULT NULL,
  `logo_path` varchar(255) DEFAULT NULL,
  `favicon_path` varchar(255) DEFAULT NULL,
  `primary_color` char(7) DEFAULT NULL,
  `secondary_color` char(7) DEFAULT NULL,
  `updated_by_user_id` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`platform_scope`),
  KEY `idx_application_branding_updated_by` (`updated_by_user_id`),
  CONSTRAINT `fk_application_branding_updated_by` FOREIGN KEY (`updated_by_user_id`) REFERENCES `user_type` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `audit_logs` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `actor_user_id` int(10) UNSIGNED DEFAULT NULL,
  `platform_scope` enum('superadmin','website','mobile','system') NOT NULL DEFAULT 'superadmin',
  `action` varchar(100) NOT NULL,
  `entity_type` varchar(100) DEFAULT NULL,
  `entity_id` varchar(100) DEFAULT NULL,
  `details` longtext,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(512) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_audit_logs_actor_created` (`actor_user_id`,`created_at`),
  KEY `idx_audit_logs_scope_created` (`platform_scope`,`created_at`),
  KEY `idx_audit_logs_entity` (`entity_type`,`entity_id`),
  CONSTRAINT `fk_audit_logs_actor` FOREIGN KEY (`actor_user_id`) REFERENCES `user_type` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

